<?php require_once 'db.php'; require_login(); $id=(int)($_GET['id']??0);$s=db()->prepare("UPDATE bookings SET status='Cancelled' WHERE id=? AND user_id=? AND status NOT IN ('Cancelled')");$s->execute([$id,$_SESSION['user_id']]);flash($s->rowCount()?'Booking cancelled. Inventory is not automatically restored in this demo.':'Booking could not be cancelled.');go('my_bookings.php'); ?>